INSERT INTO `cau_hinh` VALUES ('apriori_min_confidence','0.25','Nguong do tin cay toi thieu cho Apriori'),('apriori_min_support','0.02','Nguong do ho tro toi thieu cho Apriori'),('ban_kinh_cham_cong_m','30','Ban kinh cho phep check-in (met)'),('chatbot.bat','1','Bat (1) / tat (0) chatbot tren toan he thong.'),('chatbot.cam_on','Rất vui được giúp bạn. Bạn cần gì thêm cứ nhắn mình nhé!','Cau dap khi khach cam on.'),('chatbot.chao','Chào bạn! Mình là trợ lý ảo của nhà hàng. Mình giúp gì được cho bạn?','Cau chao mo dau.'),('chatbot.chuyen_nhan_vien','Mình chuyển bạn sang nhân viên hỗ trợ ngay. Bạn chờ một chút nhé!','Cau dap khi khach xin gap nhan vien that.'),('chatbot.danh_gia','Nhà hàng rất mong nhận góp ý của bạn. Bạn đánh giá ở mục **Đánh giá** trên website. Nếu cần xử lý gấp, mình chuyển bạn sang nhân viên ngay.','Cau tra loi khi khach muon danh gia / gop y.'),('chatbot.dat_ban','Bạn đặt bàn ở mục **Đặt bàn** trên website: chọn ngày, giờ, số khách rồi xác nhận. Nhà hàng sẽ gọi lại xác nhận trong ít phút.','Cau tra loi huong dan dat ban.'),('chatbot.dat_coc','Đặt bàn thường **không cần cọc**. Với bàn VIP hoặc nhóm đông, nhà hàng xin cọc giữ chỗ và **hoàn lại toàn bộ** khi bạn đến dùng bữa.','Cau tra loi cho cau hoi ve dat coc.'),('chatbot.dia_chi','Nhà hàng nằm tại **số 1 Võ Văn Ngân, TP. Thủ Đức, TP.HCM**. Có bãi giữ xe máy và ô tô miễn phí cho khách.','Cau tra loi cho cau hoi ve dia chi.'),('chatbot.giao_hang','Nhà hàng có **nhận mang về và giao hàng** trong bán kính 5km. Bạn đặt món ở mục Thực đơn rồi chọn hình thức Giao hàng khi thanh toán.','Cau tra loi cho cau hoi ve giao hang.'),('chatbot.gioi_thieu','Mình là **trợ lý ảo của nhà hàng**. Mình trả lời được về thực đơn, giá món, khuyến mãi, đặt bàn, giao hàng; và với tài khoản quản lý thì thêm doanh thu, tồn kho, hiệu suất nhân viên và dự báo.','Cau tra loi khi khach hoi bot lam duoc gi.'),('chatbot.gio_mo_cua','Nhà hàng mở cửa **10:00 – 22:00** tất cả các ngày trong tuần (nhận khách đến 21:30).','Cau tra loi cho cau hoi ve gio mo cua.'),('chatbot.huy_don','Bạn vào mục **Đơn của tôi** để hủy hoặc đổi giờ đơn đang chờ. Đơn bếp đã bắt đầu chế biến thì cần báo nhân viên trực tiếp.','Cau tra loi huong dan huy don.'),('chatbot.lien_he','Bạn liên hệ nhà hàng qua **hotline 0918 484 042** hoặc nhắn tin trực tiếp trong mục Chat của website nhé.','Cau tra loi cho cau hoi ve lien he.'),('chatbot.nguong_tin_cay','0.45','Nguong tin cay phan loai y dinh (Hoi quy Logistic). Chon bang quet_nguong(): 95.6% tra loi dung, 80% chan cau ngoai pham vi, chi 2.9% tu choi oan.'),('chatbot.tam_biet','Cảm ơn bạn đã ghé nhà hàng. Hẹn gặp lại bạn!','Cau tam biet.'),('chatbot.thanh_toan','Nhà hàng nhận **tiền mặt, chuyển khoản và quét mã VietQR**. Bạn có thể thanh toán tại quầy hoặc quét mã QR ngay tại bàn.','Cau tra loi cho cau hoi ve thanh toan.'),('giao_hang.ban_kinh_km','5','Ban kinh giao hang toi da (km) - ngoai vung nay website tu choi nhan don'),('giao_hang.bat','1','Bat (1) / tat (0) nhan don giao hang tren website'),('giao_hang.giu_vet_ngay','7','Giu vet duong di bao nhieu ngay roi tu don'),('giao_hang.mien_phi_tu','500000','Don tu so tien nay tro len duoc mien phi giao (0 = khong mien)'),('giao_hang.nhip_gps_giay','15','Bao nhieu giay ung dung shipper gui vi tri mot lan'),('giao_hang.tu_dong_tao_don','1','Tu tao don giao hang khi khach chon hinh thuc Giao hang (1) hay de dieu phoi tao tay (0)'),('khuon_mat_bat_gps','1','Bat rang buoc vi tri khi cham cong bang khuon mat'),('khuon_mat_bat_kiem_tra_song','1','Bat kiem tra anh song (chong gio anh in / man hinh)'),('khuon_mat_bien_an_toan','0.05','Khoang cach toi thieu giua nguoi hang 1 va hang 2'),('khuon_mat_bien_cham_ho','0.10','Nguoi khac phai giong hon chinh chu bao nhieu (cosine) thi moi coi la nghi cham ho.'),('khuon_mat_bien_do_gat','0.1','Bien do gat dau toi thieu cua thu thach chong gia mao.'),('khuon_mat_bien_do_quay','0.12','Bien do quay dau toi thieu cua thu thach chong gia mao.'),('khuon_mat_cach_nhau_giay','90','Khoang cach toi thieu giua hai lan cham cua cung nguoi'),('khuon_mat_chan_cham_ho','0','Bat (1) thi che do 1:1 tu choi khi co nguoi khac giong hon. Chi bat khi moi nhan vien co dung MOT ho so khuon mat.'),('khuon_mat_luu_anh_nhat_ky','1','Luu anh moi lan cham cong lam bang chung'),('khuon_mat_nguong_cosine','0.363','Nguong cosine de coi la cung mot nguoi (SFace)'),('khuon_mat_nguong_diem_song','0.55','Diem liveness toi thieu de chap nhan'),('khuon_mat_nguong_do_net','45','Phuong sai Laplacian toi thieu - loai anh mo'),('khuon_mat_nguong_phan_tram','50','Do khop toi thieu (%) de duoc cham cong. Cang thap cang de vao nhung cang de nhan nham.'),('khuon_mat_nhat_quan_toi_thieu','0.30','Do giong nhau toi thieu giua cac khung hinh trong mot luot cham cong.'),('khuon_mat_so_anh_toi_thieu','5','So anh mau toi thieu khi dang ky mot nhan vien'),('khuon_mat_ty_le_lai_gan','1.25','Ty le phong to khuon mat toi thieu cua thu thach \"lai gan camera\".'),('ml_service_url','http://127.0.0.1:8000','Dia chi service Machine Learning'),('nha_hang_kinh_do','106.733921','Kinh do nha hang - dung cho cham cong GPS'),('nha_hang_vi_do','10.792325','Vi do nha hang - dung cho cham cong GPS');
