INSERT INTO `chuc_danh` VALUES (1,'QLNH','Quản lý nhà hàng','QL nhà hàng',1,1,NULL,1,'Phuc vu,Bep,Ke toan,Quay,Thu ngan,Nhan vien chung','Quan ly',NULL,'Chịu trách nhiệm cuối cùng về doanh thu, chất lượng dịch vụ và nhân sự toàn nhà hàng. Duyệt các quyết định vượt thẩm quyền trưởng bộ phận.',1,0,1,'2026-08-07 04:24:06'),(2,'TLQL','Trợ lý quản lý nhà hàng','Trợ lý QL',1,2,1,1,'Phuc vu,Quay,Thu ngan,Nhan vien chung','Quan ly',NULL,'Thay mặt quản lý điều hành ca, xử lý khiếu nại khách, tổng hợp báo cáo ca.',1,1,1,'2026-08-07 04:24:06'),(3,'TRUONGLT','Trưởng lễ tân','Trưởng LT',2,3,2,1,'Quay,Phuc vu,Nhan vien chung','Quay',NULL,'Điều phối sơ đồ bàn, quản lý đặt chỗ trong ngày, phân công lễ tân theo khung giờ.',1,2,1,'2026-08-07 04:24:06'),(4,'NVLT','Lễ tân','Lễ tân',2,5,3,0,'Quay,Nhan vien chung','Quay',NULL,'Đón và tiễn khách, xác nhận đặt bàn, dẫn khách vào bàn, tiếp nhận yêu cầu ban đầu.',4,3,1,'2026-08-07 04:24:06'),(5,'GSPV','Giám sát phục vụ','GS phục vụ',3,3,2,1,'Phuc vu,Quay,Thu ngan,Nhan vien chung','Phuc vu',NULL,'Giám sát chất lượng phục vụ toàn sảnh, xử lý phàn nàn tại chỗ, duyệt giảm giá trong hạn mức.',2,4,1,'2026-08-07 04:24:06'),(6,'TOTRUONGPV','Tổ trưởng phục vụ','Tổ trưởng PV',3,4,5,1,'Phuc vu,Nhan vien chung','Phuc vu',NULL,'Phụ trách một khu vực bàn, chia việc trong tổ, kèm nhân viên mới, báo cáo giám sát.',4,5,1,'2026-08-07 04:24:06'),(7,'NVPV','Nhân viên phục vụ','Phục vụ',3,5,6,0,'Phuc vu,Nhan vien chung','Phuc vu',NULL,'Ghi món, chuyển món ra bàn, theo dõi tiến độ bàn phụ trách, dọn bàn sau khi khách rời.',12,6,1,'2026-08-07 04:24:06'),(8,'PHUBAN','Phụ bàn','Phụ bàn',3,6,6,0,'Nhan vien chung','Nhan vien chung',NULL,'Dọn dẹp, tiếp đồ dùng, hỗ trợ nhân viên phục vụ trong giờ cao điểm.',6,7,1,'2026-08-07 04:24:06'),(9,'QLBEP','Quản lý bếp','QL bếp',4,2,1,1,'Bep,Ke toan,Nhan vien chung','Quan ly',NULL,'Quản lý chi phí bếp, định mức nguyên liệu, nhà cung cấp và an toàn thực phẩm. Duyệt phiếu nhập kho.',1,8,1,'2026-08-07 04:24:06'),(10,'BEPTRUONG','Bếp trưởng','Bếp trưởng',4,2,9,1,'Bep,Nhan vien chung','Bep',NULL,'Chịu trách nhiệm thực đơn và chất lượng món. Quyết định báo hết món, điều phối toàn bộ khu bếp.',1,9,1,'2026-08-07 04:24:06'),(11,'BEPPHO','Bếp phó','Bếp phó',4,3,10,1,'Bep,Nhan vien chung','Bep',NULL,'Thay bếp trưởng điều hành ca bếp, kiểm soát tiến độ ra món và định lượng.',2,10,1,'2026-08-07 04:24:06'),(12,'TOTRUONGBEP','Tổ trưởng bếp','Tổ trưởng bếp',4,4,11,1,'Bep,Nhan vien chung','Bep',NULL,'Phụ trách một tổ chế biến (món nóng / món lạnh / nướng), chia món cho đầu bếp, kiểm món trước khi ra.',3,11,1,'2026-08-07 04:24:06'),(13,'DAUBEP','Đầu bếp','Đầu bếp',4,5,12,0,'Bep,Nhan vien chung','Bep',NULL,'Chế biến món theo đúng công thức và định lượng, cập nhật trạng thái món trên màn hình bếp.',8,12,1,'2026-08-07 04:24:06'),(14,'PHUBEP','Phụ bếp','Phụ bếp',4,6,12,0,'Nhan vien chung','Nhan vien chung',NULL,'Sơ chế nguyên liệu, chuẩn bị nguyên liệu đầu ca, hỗ trợ đầu bếp.',6,13,1,'2026-08-07 04:24:06'),(15,'TAPVUBEP','Tạp vụ bếp','Tạp vụ bếp',4,6,12,0,'Nhan vien chung','Nhan vien chung',NULL,'Vệ sinh dụng cụ, khu bếp, đảm bảo tiêu chuẩn an toàn thực phẩm.',3,14,1,'2026-08-07 04:24:06'),(16,'TRUONGBAR','Trưởng bar','Trưởng bar',5,3,2,1,'Bep,Quay,Nhan vien chung','Bep',NULL,'Quản lý công thức đồ uống, tồn kho quầy bar, phân ca nhân viên pha chế.',1,15,1,'2026-08-07 04:24:06'),(17,'NVBAR','Nhân viên pha chế','Pha chế',5,5,16,0,'Bep,Nhan vien chung','Bep',NULL,'Pha chế đồ uống theo đơn, cập nhật trạng thái đồ uống trên màn hình bếp.',3,16,1,'2026-08-07 04:24:06'),(18,'GSTN','Giám sát thu ngân','GS thu ngân',6,3,2,1,'Thu ngan,Quay,Ke toan,Nhan vien chung','Thu ngan',NULL,'Kiểm soát tiền mặt, duyệt hủy hóa đơn, đối chiếu chốt ca của các quầy.',1,17,1,'2026-08-07 04:24:06'),(19,'NVTN','Thu ngân','Thu ngân',6,5,18,0,'Thu ngan,Quay,Nhan vien chung','Thu ngan',NULL,'Thu tiền, in hóa đơn, áp mã giảm giá hợp lệ, chốt ca quầy cuối ngày.',4,18,1,'2026-08-07 04:24:06'),(20,'KTTRUONG','Kế toán trưởng','KT trưởng',7,2,1,1,'Ke toan,Thu ngan,Nhan vien chung','Ke toan',NULL,'Lập bảng lương, kiểm soát thu chi, báo cáo tài chính trình quản lý nhà hàng duyệt.',1,19,1,'2026-08-07 04:24:06'),(21,'NVKT','Kế toán viên','Kế toán',7,5,20,0,'Ke toan,Nhan vien chung','Ke toan',NULL,'Nhập liệu thu chi, theo dõi công nợ, chuẩn bị số liệu cho kế toán trưởng.',2,20,1,'2026-08-07 04:24:06'),(22,'THUKHO','Thủ kho','Thủ kho',8,4,9,1,'Bep,Ke toan,Nhan vien chung','Bep',NULL,'Nhập xuất kho theo lô, kiểm kê định kỳ, cảnh báo hạn sử dụng và tồn tối thiểu.',1,21,1,'2026-08-07 04:24:06'),(23,'NVKHO','Nhân viên kho','NV kho',8,5,22,0,'Nhan vien chung','Nhan vien chung',NULL,'Nhận hàng, sắp xếp kho, hỗ trợ kiểm kê.',2,22,1,'2026-08-07 04:24:06'),(24,'DPGH','Điều phối giao hàng','Điều phối GH',9,4,2,1,'Quay,Nhan vien chung','Nhan vien chung',NULL,'Nhận đơn giao hàng, chọn đơn vị vận chuyển, phân đơn cho shipper, theo dõi tiến độ trên bản đồ và xử lý đơn giao thất bại.',1,23,1,'2026-08-18 03:01:54'),(25,'SHIPPER','Nhân viên giao hàng','Shipper',9,5,24,0,'Nhan vien chung','Nhan vien chung',NULL,'Nhận đơn được phân, lấy hàng tại bếp, giao tận nơi, cập nhật trạng thái và bật định vị trong suốt chuyến giao.',4,24,1,'2026-08-18 03:01:54');
