  `nguong_ap_dung` float DEFAULT NULL,
  `diem_song` float DEFAULT NULL,
  `dat_kiem_tra_song` tinyint(1) DEFAULT NULL,
  `so_mat_phat_hien` int(11) DEFAULT NULL,
  `thoi_gian_xu_ly_ms` int(11) DEFAULT NULL,
  `hanh_dong` varchar(20) DEFAULT NULL,
  `khoang_cach_m` float DEFAULT NULL,
  `dia_chi_ip` varchar(45) DEFAULT NULL,
  `duong_dan_anh` varchar(300) DEFAULT NULL,
  `ghi_chu` varchar(255) DEFAULT NULL,
  `thoi_diem` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_nknd_nv` (`id_nv_du_doan`),
  KEY `idx_nknd_luc` (`thoi_diem`),
  KEY `idx_nknd_kq` (`ket_qua`)
