  `deposit_status` enum('NOT_REQUIRED','UNPAID','PENDING_PAYMENT','PAID','REFUNDED') NOT NULL DEFAULT 'NOT_REQUIRED',
  `deposit_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
