  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `manual_tables` tinyint(1) NOT NULL DEFAULT 0,
  `cancel_reason` varchar(255) DEFAULT NULL,
  `cancelled_by` enum('CUSTOMER','STAFF','SYSTEM') DEFAULT NULL,
  `refund_percent` decimal(5,2) DEFAULT NULL,
  `refund_amount` decimal(12,2) DEFAULT NULL,
  `deposit_due_at` datetime DEFAULT NULL,
  `no_show_count_at_booking` smallint(5) unsigned NOT NULL DEFAULT 0,
  `reminder_sent_at` datetime DEFAULT NULL,
  `no_show_warned_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reservation_code` (`reservation_code`),
  KEY `idx_reservation_slot` (`reservation_date`,`start_time`,`expected_end_time`,`status`),
  KEY `idx_reservation_customer` (`phone`,`customer_id`),
  KEY `idx_reservation_status` (`status`,`reservation_date`),
  KEY `idx_reservation_phone_date` (`phone`,`reservation_date`),
  KEY `idx_reservation_branch` (`branch_id`,`reservation_date`,`status`),
  CONSTRAINT `chk_reservation_guests` CHECK (`guest_count` > 0),
  CONSTRAINT `chk_reservation_duration` CHECK (`duration_minutes` > 0 and `expected_end_time` > `start_time`)
